7	
8	// V2: Validates media pool reordering — pool type (gallery/content), optional media type filter, and distinct UUID array.
9	class ReorderPoolImagesRequest extends BaseFormRequest
10	{
11	    public function rules(): array
12	    {
13	        return [
14	            'pool' => [
15	                'required',
16	                'string',
17	                Rule::in(['gallery', 'content']),
18	            ],
19	            'media_type' => [
20	                'sometimes',
21	                'nullable',
22	                'string',
23	                Rule::in(['image', 'video']),
24	            ],
25	            'ids' => ['required', 'array', 'min:1'],
26	            'ids.*' => ['required', 'uuid', 'distinct'],
27	        ];
28	    }
29	
30	    protected function prepareForValidation(): void
31	    {
32	        if (is_string($this->pool ?? null)) {
33	            $this->merge(['pool' => strtolower(trim($this->pool))]);
34	        }
35	        if (is_string($this->media_type ?? null)) {
36	            $this->merge(['media_type' => strtolower(trim($this->media_type))]);
37	        }
38	    }
39	}
