22	{
23	    use ResolveCurrentProfessional;
24	    use ResolveCurrentSite;
25	
26	    public function index(Request $request): JsonResponse
27	    {
28	        $pro = $this->currentProfessional($request);
29	        $pro->loadMissing('site');
30	        $site = $this->currentSite($pro);
31	
32	        // Return the document regardless of is_active so draft docs surface in
33	        // the dashboard — the frontend publish toggle flips is_active directly.
34	        $media = SiteMedia::query()
35	            ->where('site_id', $site->id)
36	            ->where('pool', SiteMedia::POOL_DOCUMENTS)
37	            ->whereNull('deleted_at')
38	            ->first();
39	
40	        return $this->success([
41	            'document' => $media ? $this->buildDocumentPayload($media) : null,
42	        ]);
43	    }
44	
45	    public function store(UploadDocumentRequest $request): JsonResponse
46	    {
47	        $pro = $this->currentProfessional($request);
48	        $pro->loadMissing('site');
49	        $site = $this->currentSite($pro);
50	
51	        // Brand accounts are excluded per product spec — they have Shopify
52	        // for catalogue assets and don't get the generic document slot.
53	        if ($pro->professional_type === 'brand') {
54	            return $this->error('Documents section not available for brand accounts.', 403);
55	        }
56	
57	        // Double MIME-check via finfo — prevents Content-Type header spoofing
58	        // on top of the mimes: validation rule which trusts the client header.
59	        $file = $request->file('file');
60	        $actualMime = (new \finfo(FILEINFO_MIME_TYPE))->file($file->getRealPath());
61	        $allowed = ['application/pdf', 'image/jpeg', 'image/png'];
62	        if (! in_array($actualMime, $allowed, true)) {
63	            return $this->error('Document bytes do not match an accepted file type.', 415);
64	        }
65	
66	        $title = trim((string) $request->validated('title'));
67	        $caption = $this->normaliseOptionalString($request->validated('caption'));
68	        // basename() removes path traversal components; control-char strip (incl. CRLF)
69	        // prevents header injection if this value ever appears in Content-Disposition.
70	        $rawFilename = basename((string) $file->getClientOriginalName());
71	        $rawFilename = (string) preg_replace('/[\x00-\x1F\x7F]/', '', $rawFilename);
72	        $originalFilename = substr($rawFilename, 0, 255);
73	
74	        // Flat-replace: inside one transaction, soft-delete the existing row
75	        // (if any), create the new row, stream the file to R2, and set the path.
76	        // The old row's R2 bytes are deleted AFTER commit so a transaction
77	        // rollback doesn't leave an active row pointing at missing bytes.
78	        //
79	        // If the transaction closure throws AFTER we've streamed the new file
80	        // to R2, the uploaded bytes would be orphaned (row gone, file remains).
81	        // Track the new path and clean it up in the catch branch below.
82	        $previousPath = null;
83	        $newUploadedPath = null;
84	        try {
85	            $media = DB::transaction(function () use ($site, $pro, $file, $actualMime, $title, $caption, $originalFilename, &$previousPath, &$newUploadedPath) {
86	                if (DB::getDriverName() === 'pgsql') {
87	                    DB::select('select pg_advisory_xact_lock(hashtext(?))', ["site-documents:{$site->id}"]);
88	                }
89	
90	                // Flat-replace targets any non-deleted doc (including drafts)
91	                // so uploading a new file always takes over the single slot.
92	                $existing = SiteMedia::query()
93	                    ->where('site_id', $site->id)
94	                    ->where('pool', SiteMedia::POOL_DOCUMENTS)
95	                    ->whereNull('deleted_at')
96	                    ->first();
97	
98	                if ($existing) {
99	                    // Capture the path for post-commit R2 cleanup.
100	                    $previousPath = (string) $existing->path;
101	                    // Suppress the old row's `deleted` observer event during
102	                    // flat-replace — the new row's `saved` event a few lines
103	                    // below will trigger section-visibility reevaluation once.
104	                    // Without this, both events fire post-commit and do the
105	                    // same DB read + check in sequence (wasted work).
106	                    SiteMedia::withoutEvents(function () use ($existing): void {
107	                        $existing->delete();
108	                    });
109	                }
110	
111	                // Extension is derived from the actual MIME — never from the
112	                // client-supplied filename (spoofable).
113	                $ext = match ($actualMime) {
114	                    'application/pdf' => 'pdf',
115	                    'image/jpeg' => 'jpg',
116	                    'image/png' => 'png',
117	                };
118	
119	                $media = SiteMedia::create([
120	                    'site_id' => $site->id,
121	                    'pool' => SiteMedia::POOL_DOCUMENTS,
122	                    'path' => '',
123	                    'alt_text' => $title,
124	                    'caption' => $caption,
125	                    'sort_order' => 0,
126	                    'is_active' => true,
127	                    'media_type' => SiteMedia::MEDIA_TYPE_DOCUMENT,
128	                    'processing_state' => SiteMedia::PROCESSING_STATE_READY,
129	                    'original_mime' => $actualMime,
130	                    'original_filename' => $originalFilename,
131	                    'original_size_bytes' => $file->getSize(),
132	                ]);
133	
134	                // Stream to R2 (not in-memory) — matches the video upload path
135	                // so 10 MB PDFs don't peg worker memory.
136	                $mediaDisk = config('sidest.media_disk');
137	                $path = "documents/{$pro->id}/{$media->id}/original.{$ext}";
138	                $stream = fopen($file->getRealPath(), 'rb');
139	                Storage::disk($mediaDisk)->put($path, $stream, 'public');
140	                if (is_resource($stream)) {
141	                    fclose($stream);
142	                }
143	                $newUploadedPath = $path;
144	
145	                $media->update(['path' => $path]);
146	
147	                return $media;
148	            });
149	        } catch (\Throwable $e) {
150	            // Transaction failed after the R2 put succeeded — clean up the
151	            // orphaned bytes so we don't leak storage on retries.
152	            if ($newUploadedPath !== null) {
153	                try {
154	                    Storage::disk(config('sidest.media_disk'))->delete($newUploadedPath);
155	                } catch (\Throwable $cleanupError) {
156	                    Log::warning('Failed to clean up orphaned document R2 object after transaction failure', [
157	                        'path' => $newUploadedPath,
158	                        'error' => $cleanupError->getMessage(),
159	                    ]);
160	                }
161	            }
162	            throw $e;
163	        }
164	
165	        // Post-commit: delete old R2 bytes. Safe to run outside the txn because
166	        // the old row is already soft-deleted (so no reader will try to fetch
167	        // the old path), and if this delete fails we just leak bytes — not a
168	        // correctness issue. If the transaction had rolled back, $previousPath
169	        // would stay null and this is a no-op.
170	        if ($previousPath !== null && $previousPath !== '') {
171	            try {
172	                Storage::disk(config('sidest.media_disk'))->delete($previousPath);
173	            } catch (\Throwable $e) {
174	                Log::warning('Failed to delete previous document R2 object after commit', [
175	                    'path' => $previousPath,
176	                    'error' => $e->getMessage(),
177	                ]);
178	            }
179	        }
180	
181	        app(SiteCacheService::class)->invalidateSite($site);
182	
183	        return $this->success(['document' => $this->buildDocumentPayload($media)], 201);
184	    }
