186	    /**
187	     * Edit document title and/or caption. isDirty-guarded so no-op PATCHes
188	     * don't churn the public-site cache.
189	     */
190	    public function update(UpdateDocumentRequest $request, SiteMedia $document): JsonResponse
191	    {
192	        $pro = $this->currentProfessional($request);
193	        $pro->loadMissing('site');
194	        $site = $this->currentSite($pro);
195	
196	        // Ownership check. Route model binding already 404s on soft-deleted rows
197	        // (SoftDeletes trait). We intentionally allow is_active = false so the
198	        // publish toggle can flip a draft document back to live.
199	        abort_unless(
200	            $document->site_id === $site->id
201	            && $document->pool === SiteMedia::POOL_DOCUMENTS,
202	            404
203	        );
204	
205	        $data = $request->validated();
206	        $update = [];
207	
208	        if (array_key_exists('title', $data)) {
209	            $update['alt_text'] = $this->normaliseOptionalString($data['title']);
210	        }
211	
212	        if (array_key_exists('caption', $data)) {
213	            $update['caption'] = $this->normaliseOptionalString($data['caption']);
214	        }
215	
216	        // is_enabled maps to is_active — the publish toggle flips this directly.
217	        if (array_key_exists('is_enabled', $data)) {
218	            $update['is_active'] = (bool) $data['is_enabled'];
219	        }
220	
221	        $changed = false;
222	        if (! empty($update)) {
223	            $document->fill($update);
224	            if ($document->isDirty(['alt_text', 'caption', 'is_active'])) {
225	                $document->save();
226	                $changed = true;
227	            }
228	        }
229	
230	        if ($changed) {
231	            app(SiteCacheService::class)->invalidateSite($site);
232	        }
233	
234	        return $this->success(['document' => $this->buildDocumentPayload($document->fresh())]);
235	    }
236	
237	    /**
238	     * Soft-delete the row and synchronously delete the R2 bytes (no
239	     * versioning, so there's no archival value in keeping bytes around).
240	     */
241	    public function destroy(Request $request, SiteMedia $document): JsonResponse
242	    {
243	        $pro = $this->currentProfessional($request);
244	        $pro->loadMissing('site');
245	        $site = $this->currentSite($pro);
246	
247	        // Ownership check — allows deleting draft (is_active = false) docs too.
248	        // Route model binding already 404s on soft-deleted rows.
249	        abort_unless(
250	            $document->site_id === $site->id
251	            && $document->pool === SiteMedia::POOL_DOCUMENTS,
252	            404
253	        );
254	
255	        try {
256	            Storage::disk(config('sidest.media_disk'))->delete((string) $document->path);
257	        } catch (\Throwable $e) {
258	            Log::warning('Failed to delete document R2 object on destroy', [
259	                'media_id' => $document->id,
260	                'path' => $document->path,
261	                'error' => $e->getMessage(),
262	            ]);
263	        }
264	
265	        $document->delete();
266	
267	        app(SiteCacheService::class)->invalidateSite($site);
268	
269	        return $this->success(['deleted' => true]);
270	    }
271	
272	    /**
273	     * @return array{id: string, title: string|null, caption: string|null, is_enabled: bool, original_mime: string|null, original_size_bytes: int|null, original_filename: string|null, preview_url: string, download_url: string, created_at: mixed, updated_at: mixed}
274	     */
275	    private function buildDocumentPayload(SiteMedia $media): array
276	    {
277	        $mediaDisk = config('sidest.media_disk');
278	        $previewUrl = Storage::disk($mediaDisk)->url((string) $media->path);
279	
280	        return [
281	            'id' => $media->id,
282	            'title' => $media->alt_text,
283	            'caption' => $media->caption,
284	            // is_enabled maps to is_active — the publish toggle reads and writes this.
285	            'is_enabled' => (bool) $media->is_active,
286	            'original_mime' => $media->original_mime,
287	            'original_size_bytes' => $media->original_size_bytes,
288	            'original_filename' => $media->original_filename,
289	            'preview_url' => $previewUrl,
290	            'download_url' => '/api/public/documents/'.$media->id.'/download',
291	            'created_at' => $media->created_at,
292	            'updated_at' => $media->updated_at,
293	        ];
294	    }
295	
296	    /**
297	     * Trim; coerce empty/whitespace-only strings to NULL so NULL and ""
298	     * mean the same thing at rest.
299	     */
300	    private function normaliseOptionalString(?string $raw): ?string
301	    {
302	        if ($raw === null) {
303	            return null;
304	        }
305	
306	        $trimmed = trim($raw);
307	
308	        return $trimmed === '' ? null : $trimmed;
309	    }
310	}
