30	// V2: Media management (images, videos, brand logos, placeholders). Handles upload → processing pipeline → R2 storage.
31	class ProfessionalUploadController extends ApiController
32	{
33	    use ResolveCurrentProfessional;
34	    use ResolveCurrentSite;
35	
36	    public function __construct(
37	        private readonly ImageVariantService $mediaService,
38	        private readonly BrandDesignMediaService $brandDesign,
39	        private readonly VideoVariantService $videoVariant,
40	    ) {}
41	
42	    /**
43	     * Upload an image or video to a pool (gallery or content).
44	     *
45	     * Accepts exactly one of: `image` (JPEG/PNG/WebP) or `video` (MP4/MOV/WebM).
46	     * Returns immediately; processing runs async on the appropriate queue.
47	     *
48	     * POST /api/uploads
49	     *   { pool: gallery|content, image?: <file>, video?: <file>, alt_text?: string }
50	     */
51	    public function upload(UploadImageRequest $request): JsonResponse
52	    {
53	        $pro = $this->currentProfessional($request);
54	        $pro->loadMissing('site');
55	        $site = $this->currentSite($pro);
56	
57	        $pool = $request->validated('pool');
58	        $isVideo = $request->hasFile('video');
59	        $file = $isVideo ? $request->file('video') : $request->file('image');
60	        $mediaType = $isVideo ? SiteMedia::MEDIA_TYPE_VIDEO : SiteMedia::MEDIA_TYPE_IMAGE;
61	
62	        Log::info('Media upload started', [
63	            'pro_id' => $pro->id,
64	            'site_id' => $site->id,
65	            'pool' => $pool,
66	            'media_type' => $mediaType,
67	            'file_size_kb' => $file->getSize() / 1024,
68	        ]);
69	
70	        // Pool limit is shared across media types (images + videos count toward the same cap).
71	        $maxItems = (int) config("sidest.image_pools.{$pool}.max", 5);
72	
73	        $activeCount = SiteMedia::query()
74	            ->where('site_id', $site->id)
75	            ->where('pool', $pool)
76	            ->where('is_active', true)
77	            ->count();
78	
79	        if ($activeCount >= $maxItems) {
80	            return $this->error(
81	                ucfirst($pool)." media limit reached (max {$maxItems}).", 422
82	            );
83	        }
84	
85	        // --- Probe video container before touching DB or storage ---
86	        // Validates the container with ffprobe while the file is still in PHP's temp dir.
87	        // Rejects unreadable containers or files with no video stream immediately,
88	        // before we spend a DB row, R2 storage, or a worker queue slot on them.
89	        if ($isVideo) {
90	            try {
91	                $this->videoVariant->probeAndValidate($file->getRealPath());
92	            } catch (\RuntimeException $e) {
93	                return $this->error('Invalid video file: '.$e->getMessage(), 422);
94	            }
95	        }
96	
97	        // --- Create SiteMedia row (with advisory lock for race safety) ---
98	        $media = DB::transaction(function () use ($site, $pool, $maxItems, $request, $mediaType, $file) {
99	            if (DB::getDriverName() === 'pgsql') {
100	                DB::select('select pg_advisory_xact_lock(hashtext(?))', ["site-images:{$site->id}"]);
101	            }
102	
103	            $siteImages = SiteMedia::query()
104	                ->where('site_id', $site->id)
105	                ->lockForUpdate()
106	                ->get(['id', 'pool', 'sort_order', 'is_active']);
107	
108	            $activeCount = $siteImages
109	                ->where('pool', $pool)
110	                ->where('is_active', true)
111	                ->count();
112	
113	            if ($activeCount >= $maxItems) {
114	                abort(422, ucfirst($pool)." media limit reached (max {$maxItems}).");
115	            }
116	
117	            $maxSort = $siteImages->max('sort_order');
118	
119	            $media = SiteMedia::create([
120	                'site_id' => $site->id,
121	                'pool' => $pool,
122	                'path' => '',
123	                'alt_text' => $request->validated('alt_text'),
124	                'caption' => $this->normaliseOptionalString($request->validated('caption')),
125	                'sort_order' => is_null($maxSort) ? 0 : ((int) $maxSort + 1),
126	                'is_active' => true,
127	                'media_type' => $mediaType,
128	                'processing_state' => SiteMedia::PROCESSING_STATE_PENDING,
129	                'original_mime' => $file->getMimeType(),
130	                'original_size_bytes' => $file->getSize(),
131	            ]);
132	
133	            Log::info('SiteMedia row created', ['media_id' => $media->id, 'media_type' => $mediaType]);
134	
135	            return $media;
136	        });
137	
138	        // --- Store original on media disk ---
139	        $basePath = $isVideo
140	            ? "videos/{$pro->id}/{$media->id}"
141	            : "images/{$pro->id}/{$media->id}";
142	
143	        try {
144	            $mediaDisk = $this->mediaService->resolvedDiskName();
145	
146	            Log::info('Storing original to media disk', [
147	                'media_id' => $media->id,
148	                'base_path' => $basePath,
149	                'media_disk' => $mediaDisk,
150	            ]);
151	
152	            if ($isVideo) {
153	                // Stream large video files to avoid loading full content into memory.
154	                $ext = $this->mediaService->safeExtension($file->getClientOriginalExtension() ?? '', 'mp4');
155	                $hash = substr(hash_file('sha256', $file->getRealPath()), 0, 16);
156	                $path = "{$basePath}/original_{$hash}.{$ext}";
157	                $stream = fopen($file->getRealPath(), 'rb');
158	                Storage::disk($mediaDisk)->put($path, $stream, 'public');
159	                if (is_resource($stream)) {
160	                    fclose($stream);
161	                }
162	                $originalPath = $path;
163	            } else {
164	                $originalPath = $this->mediaService->storeOriginal($file, $basePath);
165	            }
166	
167	            Log::info('Original stored successfully', ['media_id' => $media->id, 'path' => $originalPath]);
168	        } catch (\Exception $e) {
169	            Log::error('Failed to store original', [
170	                'media_id' => $media->id,
171	                'error' => $e->getMessage(),
172	            ]);
173	            $media->delete();
174	
175	            return $this->error('Failed to store file: '.$e->getMessage(), 500);
176	        }
177	
178	        $media->update(['path' => $originalPath]);
179	
180	        // --- Dispatch processing job ---
181	        if ($isVideo) {
182	            try {
183	                $this->dispatchVideoJob($media->id, $originalPath, $basePath);
184	            } catch (Throwable $e) {
185	                Log::error('Video upload dispatch failed; rolling back media item.', [
186	                    'site_id' => $site->id,
187	                    'media_id' => $media->id,
188	                    'pool' => $pool,
189	                    'error' => $e->getMessage(),
190	                    'exception' => get_class($e),
191	                ]);
192	
193	                $mediaDisk = $this->mediaService->resolvedDiskName();
194	                try {
195	                    Storage::disk($mediaDisk)->delete($originalPath);
196	                } catch (Throwable $cleanupError) {
197	                    Log::warning('Failed to cleanup original video after dispatch failure.', [
198	                        'site_id' => $site->id,
199	                        'media_id' => $media->id,
200	                        'pool' => $pool,
201	                        'path' => $originalPath,
202	                        'media_disk' => $mediaDisk,
203	                        'error' => $cleanupError->getMessage(),
204	                    ]);
205	                }
206	
207	                $media->delete();
208	                app(SiteCacheService::class)->invalidateSite($site);
209	
210	                return $this->error(
211	                    'Video processing is temporarily unavailable. Please try again.',
212	                    503
213	                );
214	            }
215	        } else {
216	            $this->dispatchImageJob($media->id, $originalPath, $basePath);
217	        }
218	
219	        app(SiteCacheService::class)->invalidateSite($site);
220	
221	        // Refresh model state (sync mode may have updated processing_state to 'ready').
222	        $media->refresh();
223	        $media->load('mediaVariants');
224	        $payload = $this->buildMediaPayload($media, includeVariants: true);
225	
226	        return $this->success($payload, 201);
227	    }
