275	
276	        return $this->success([
277	            'images' => $items,
278	            'limits' => [
279	                'gallery' => config('sidest.image_pools.gallery.max', 5),
280	                'content' => config('sidest.image_pools.content.max', 5),
281	            ],
282	        ]);
