414	                (string) $pro->id,
415	                ConfirmationPreferenceService::ACTION_DELETE_MEDIA
416	            );
417	        }
418	
419	        app(SiteCacheService::class)->invalidateSite($site);
420	
421	        return $this->success(['deleted' => true]);
422	    }
